// Deliberately a keyword screen, not a classifier.
// It is a safety net that must never depend on the LLM being available,
// and it errs towards flagging. The LLM answer is still produced; this
// only decides whether a human is told and whether help lines are added.
const CRITICAL = [
  'убить себя', 'покончить с собой', 'суицид', 'не хочу жить', 'хочу умереть',
  'сведу счёты с жизнью', 'kill myself', 'end my life', 'suicide',
];
const HIGH = [
  'резать себя', 'причинить себе вред', 'самоповреждение', 'self-harm',
  'больше не могу так жить', 'смысла жить нет',
];
const MEDIUM = ['паническая атака', 'меня бьют', 'насилие', 'panic attack', 'abuse'];

function severityOf(text) {
  const haystack = (text || '').toLowerCase();
  if (CRITICAL.some((n) => haystack.includes(n))) return 'critical';
  if (HIGH.some((n) => haystack.includes(n))) return 'high';
  if (MEDIUM.some((n) => haystack.includes(n))) return 'medium';
  return null;
}

return $input.all().map((item) => {
  const severity = severityOf(item.json.text);
  return {
    json: {
      telegram_id: item.json.telegram_id,
      text: item.json.text,
      severity,
      flagged: severity !== null,
    },
  };
});

// What the calling workflow gets back.
const screened = $('Screen text').first().json;
return [{
  json: {
    flagged: screened.flagged,
    severity: screened.severity,
    append_to_reply: screened.flagged
      ? '\n\n—\nЕсли сейчас тяжело: я рядом, но я не заменяю помощь специалиста. Пожалуйста, свяжись с близким человеком или со службой экстренной психологической помощи в твоей стране.'
      : '',
  },
}];
